CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE legal_entities (id text PRIMARY KEY, name text NOT NULL UNIQUE, jurisdiction text NOT NULL, entity_type text NOT NULL, reporting_currency text, status text NOT NULL DEFAULT 'CONFIRMED');
CREATE TABLE brands (id text PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE stores (id text PRIMARY KEY, brand_id text NOT NULL REFERENCES brands(id), name text NOT NULL, domain text, accent_color text NOT NULL, legal_entity_id text REFERENCES legal_entities(id), mapping_status text NOT NULL DEFAULT 'UNMAPPED', UNIQUE(brand_id,name));
CREATE TABLE users (id text PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text, role text NOT NULL CHECK(role IN ('OWNER','OPERATIONS_MANAGER')), is_demo boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_attempts (identifier text PRIMARY KEY, failures integer NOT NULL DEFAULT 0, blocked_until timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id text PRIMARY KEY, brand_id text NOT NULL REFERENCES brands(id), name text NOT NULL, status text NOT NULL DEFAULT 'UNMAPPED');
CREATE TABLE product_aliases (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id), alias text NOT NULL);
CREATE TABLE variants (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id), store_id text REFERENCES stores(id), sku text NOT NULL, external_id text, UNIQUE(store_id,sku));
CREATE TABLE bundle_components (bundle_variant_id text NOT NULL REFERENCES variants(id), component_variant_id text NOT NULL REFERENCES variants(id), quantity integer NOT NULL CHECK(quantity>0), PRIMARY KEY(bundle_variant_id,component_variant_id));
CREATE TABLE vendors (id text PRIMARY KEY, name text NOT NULL, kind text NOT NULL, external_id text);
CREATE TABLE warehouses (id text PRIMARY KEY, name text NOT NULL, country text, supplier_id text REFERENCES vendors(id));
CREATE TABLE supplier_skus (id text PRIMARY KEY, supplier_id text NOT NULL REFERENCES vendors(id), sku text NOT NULL, product_id text REFERENCES products(id), UNIQUE(supplier_id,sku));
CREATE TABLE sku_mappings (variant_id text NOT NULL REFERENCES variants(id), supplier_sku_id text NOT NULL REFERENCES supplier_skus(id), status text NOT NULL DEFAULT 'MANUAL', PRIMARY KEY(variant_id,supplier_sku_id));
CREATE TABLE invoices (id text PRIMARY KEY, vendor text NOT NULL, invoice_number text NOT NULL, legal_entity_id text NOT NULL REFERENCES legal_entities(id), store_id text NOT NULL REFERENCES stores(id), currency text NOT NULL CHECK(currency IN ('USD','EUR','GBP')), total_minor bigint NOT NULL CHECK(total_minor>0), invoice_date date NOT NULL, effective_date date NOT NULL, due_date date NOT NULL, payment_date date, status text NOT NULL CHECK(status IN ('DRAFT','CONFIRMED','PAID')), source text NOT NULL, verification_status text NOT NULL, notes text NOT NULL DEFAULT '', created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(legal_entity_id,vendor,invoice_number));
CREATE TABLE invoice_items (id text PRIMARY KEY, invoice_id text NOT NULL REFERENCES invoices(id), product_id text NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK(quantity>0), bundle_quantity integer NOT NULL CHECK(bundle_quantity>0), product_minor bigint NOT NULL CHECK(product_minor>=0), packaging_minor bigint NOT NULL CHECK(packaging_minor>=0), fulfillment_minor bigint NOT NULL CHECK(fulfillment_minor>=0), shipping_minor bigint NOT NULL CHECK(shipping_minor>=0), other_minor bigint NOT NULL CHECK(other_minor>=0));
CREATE TABLE invoice_attachments (id text PRIMARY KEY, invoice_id text NOT NULL REFERENCES invoices(id), original_name text NOT NULL, mime_type text NOT NULL, storage_key text NOT NULL UNIQUE, size_bytes integer NOT NULL CHECK(size_bytes>0), sha256 text NOT NULL);
CREATE TABLE cost_rules (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id), store_id text NOT NULL REFERENCES stores(id), legal_entity_id text NOT NULL REFERENCES legal_entities(id), supplier_id text REFERENCES vendors(id), sku text, country text, batch text, bundle_quantity integer NOT NULL CHECK(bundle_quantity>0), currency text NOT NULL, product_minor bigint NOT NULL CHECK(product_minor>=0), packaging_minor bigint NOT NULL CHECK(packaging_minor>=0), fulfillment_minor bigint NOT NULL CHECK(fulfillment_minor>=0), shipping_minor bigint NOT NULL CHECK(shipping_minor>=0), other_minor bigint NOT NULL CHECK(other_minor>=0), effective_start date NOT NULL, effective_end date, version integer NOT NULL DEFAULT 1, invoice_id text REFERENCES invoices(id), source text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(effective_end IS NULL OR effective_end>effective_start));
CREATE TABLE orders (id text PRIMARY KEY, store_id text NOT NULL REFERENCES stores(id), legal_entity_id text REFERENCES legal_entities(id), external_id text NOT NULL, ordered_at timestamptz NOT NULL, currency text NOT NULL, gross_minor bigint NOT NULL, discount_minor bigint NOT NULL DEFAULT 0, platform_refund_minor bigint NOT NULL DEFAULT 0, internal_refund_minor bigint, processing_minor bigint NOT NULL DEFAULT 0, source text NOT NULL, status text NOT NULL, UNIQUE(store_id,external_id));
CREATE TABLE order_items (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), product_id text NOT NULL REFERENCES products(id), sku text, quantity integer NOT NULL CHECK(quantity>0), bundle_quantity integer NOT NULL CHECK(bundle_quantity>0));
CREATE TABLE order_costs (id text PRIMARY KEY, order_item_id text NOT NULL REFERENCES order_items(id), cost_rule_id text NOT NULL REFERENCES cost_rules(id), rule_version integer NOT NULL, estimated_minor bigint NOT NULL, actual_minor bigint, components jsonb NOT NULL, calculated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cost_reconciliations (id text PRIMARY KEY, order_cost_id text NOT NULL REFERENCES order_costs(id), invoice_item_id text NOT NULL REFERENCES invoice_items(id), actual_minor bigint NOT NULL, estimate_minor bigint NOT NULL, reason text NOT NULL, created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), external_id text, platform_minor bigint NOT NULL, internal_minor bigint, refunded_at timestamptz NOT NULL, restocked boolean, recovered_cogs_minor bigint, fee_impact_minor bigint, reason text, source text NOT NULL);
CREATE TABLE prepaid_cost_pools (id text PRIMARY KEY, legal_entity_id text NOT NULL REFERENCES legal_entities(id), store_id text REFERENCES stores(id), purchased_quantity integer NOT NULL CHECK(purchased_quantity>0), remaining_quantity integer NOT NULL CHECK(remaining_quantity>=0), total_minor bigint NOT NULL, currency text NOT NULL, purchased_at timestamptz NOT NULL, CHECK(remaining_quantity<=purchased_quantity));
CREATE TABLE prepaid_consumption (id text PRIMARY KEY, pool_id text NOT NULL REFERENCES prepaid_cost_pools(id), order_item_id text NOT NULL REFERENCES order_items(id), quantity integer NOT NULL CHECK(quantity>0), allocated_minor bigint NOT NULL, UNIQUE(pool_id,order_item_id));
CREATE TABLE cash_accounts (id text PRIMARY KEY, legal_entity_id text NOT NULL REFERENCES legal_entities(id), store_id text REFERENCES stores(id), name text NOT NULL, currency text NOT NULL);
CREATE TABLE cash_balance_snapshots (id text PRIMARY KEY, account_id text NOT NULL REFERENCES cash_accounts(id), available_minor bigint NOT NULL, pending_minor bigint NOT NULL DEFAULT 0, source text NOT NULL, status text NOT NULL, observed_at timestamptz NOT NULL);
CREATE TABLE obligations (id text PRIMARY KEY, legal_entity_id text NOT NULL REFERENCES legal_entities(id), store_id text NOT NULL REFERENCES stores(id), invoice_id text UNIQUE REFERENCES invoices(id), title text NOT NULL, category text NOT NULL, currency text NOT NULL CHECK(currency IN ('USD','EUR','GBP')), amount_minor bigint NOT NULL CHECK(amount_minor>0), due_at timestamptz NOT NULL, filing_date date, period text, jurisdiction text, scope text NOT NULL DEFAULT 'COMPANY' CHECK(scope IN ('COMPANY','PERSONAL')), status text NOT NULL CHECK(status IN ('SCHEDULED','PAID','CANCELLED')), paid_at timestamptz, source text NOT NULL, verification_status text NOT NULL, created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expected_inflows (id text PRIMARY KEY, legal_entity_id text NOT NULL REFERENCES legal_entities(id), store_id text NOT NULL REFERENCES stores(id), title text NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>0), currency text NOT NULL, expected_at timestamptz NOT NULL, source text NOT NULL, status text NOT NULL);
CREATE TABLE recurring_expenses (id text PRIMARY KEY, legal_entity_id text NOT NULL REFERENCES legal_entities(id), store_id text REFERENCES stores(id), vendor text NOT NULL, category text NOT NULL, amount_minor bigint NOT NULL, currency text NOT NULL, frequency text NOT NULL, next_due date NOT NULL, active boolean NOT NULL DEFAULT true, source text NOT NULL, last_verified_at timestamptz NOT NULL, price_history jsonb NOT NULL DEFAULT '[]');
CREATE TABLE ad_accounts (id text PRIMARY KEY, platform text NOT NULL, store_id text NOT NULL REFERENCES stores(id), legal_entity_id text REFERENCES legal_entities(id), external_id text, currency text NOT NULL);
CREATE TABLE ad_spend (id text PRIMARY KEY, account_id text NOT NULL REFERENCES ad_accounts(id), spend_date date NOT NULL, actual_minor bigint NOT NULL, source text NOT NULL, status text NOT NULL, UNIQUE(account_id,spend_date));
CREATE TABLE ad_budgets (id text PRIMARY KEY, account_id text NOT NULL REFERENCES ad_accounts(id), daily_minor bigint NOT NULL, effective_at timestamptz NOT NULL, source text NOT NULL);
CREATE TABLE meta_billing_accounts (id text PRIMARY KEY, ad_account_id text NOT NULL REFERENCES ad_accounts(id), legal_entity_id text REFERENCES legal_entities(id), name text NOT NULL, currency text NOT NULL);
CREATE TABLE meta_credit_snapshots (id text PRIMARY KEY, billing_account_id text NOT NULL REFERENCES meta_billing_accounts(id), limit_minor bigint NOT NULL, outstanding_minor bigint NOT NULL, observed_at timestamptz NOT NULL, source text NOT NULL, status text NOT NULL);
CREATE TABLE meta_payments (id text PRIMARY KEY, billing_account_id text NOT NULL REFERENCES meta_billing_accounts(id), obligation_id text REFERENCES obligations(id), amount_minor bigint NOT NULL, currency text NOT NULL, stage text NOT NULL CHECK(stage IN ('PLANNED','INITIATED','SENT','RECEIVED','CREDIT_RESTORED')), expected_clearing_at timestamptz, actual_clearing_at timestamptz);
CREATE TABLE inventory_snapshots (id text PRIMARY KEY, supplier_sku_id text NOT NULL REFERENCES supplier_skus(id), warehouse_id text NOT NULL REFERENCES warehouses(id), available integer, reserved integer, on_hand integer, observed_at timestamptz NOT NULL, source text NOT NULL, status text NOT NULL);
CREATE TABLE inventory_adjustments (id text PRIMARY KEY, snapshot_id text NOT NULL REFERENCES inventory_snapshots(id), quantity integer NOT NULL, reason text NOT NULL, created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_orders (id text PRIMARY KEY, supplier_id text NOT NULL REFERENCES vendors(id), legal_entity_id text NOT NULL REFERENCES legal_entities(id), status text NOT NULL, ordered_at timestamptz NOT NULL, currency text NOT NULL, obligation_id text REFERENCES obligations(id));
CREATE TABLE purchase_order_items (id text PRIMARY KEY, purchase_order_id text NOT NULL REFERENCES purchase_orders(id), supplier_sku_id text NOT NULL REFERENCES supplier_skus(id), quantity integer NOT NULL CHECK(quantity>0), cost_minor bigint NOT NULL);
CREATE TABLE inbound_shipments (id text PRIMARY KEY, purchase_order_id text REFERENCES purchase_orders(id), destination_warehouse_id text NOT NULL REFERENCES warehouses(id), status text NOT NULL, etd timestamptz, eta timestamptz, actual_arrival_at timestamptz, carrier text, tracking text, source text NOT NULL);
CREATE TABLE shipment_items (id text PRIMARY KEY, shipment_id text NOT NULL REFERENCES inbound_shipments(id), supplier_sku_id text NOT NULL REFERENCES supplier_skus(id), quantity integer NOT NULL CHECK(quantity>0));
CREATE TABLE shipment_events (id text PRIMARY KEY, shipment_id text NOT NULL REFERENCES inbound_shipments(id), status text NOT NULL, occurred_at timestamptz NOT NULL, source text NOT NULL);
CREATE TABLE integration_connections (id text PRIMARY KEY, platform text NOT NULL, store_id text REFERENCES stores(id), external_account_id text, status text NOT NULL DEFAULT 'UNAVAILABLE', capabilities jsonb NOT NULL DEFAULT '{}');
CREATE TABLE integration_syncs (id text PRIMARY KEY, connection_id text NOT NULL REFERENCES integration_connections(id), started_at timestamptz NOT NULL, completed_at timestamptz, status text NOT NULL, cursor_value text, error_message text);
CREATE TABLE fx_rates (id text PRIMARY KEY, base_currency text NOT NULL, quote_currency text NOT NULL, rate numeric(20,10) NOT NULL CHECK(rate>0), source text NOT NULL, observed_at timestamptz NOT NULL);
CREATE TABLE alerts (id text PRIMARY KEY, store_id text REFERENCES stores(id), severity text NOT NULL, kind text NOT NULL, reason text NOT NULL, affected_record_id text, recommendation text, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, table_name text NOT NULL, record_id text NOT NULL, action text NOT NULL, previous_value jsonb, next_value jsonb, actor_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION audit_financial_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 INSERT INTO audit_logs(table_name,record_id,action,previous_value,next_value,actor_id) VALUES(TG_TABLE_NAME,COALESCE(NEW.id,OLD.id),TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END,current_setting('app.actor_id',true));
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END; $$;
CREATE TRIGGER invoice_audit AFTER INSERT OR UPDATE OR DELETE ON invoices FOR EACH ROW EXECUTE FUNCTION audit_financial_change();
CREATE TRIGGER cost_rule_audit AFTER INSERT OR UPDATE OR DELETE ON cost_rules FOR EACH ROW EXECUTE FUNCTION audit_financial_change();
CREATE TRIGGER obligation_audit AFTER INSERT OR UPDATE OR DELETE ON obligations FOR EACH ROW EXECUTE FUNCTION audit_financial_change();
CREATE TRIGGER balance_audit AFTER INSERT OR UPDATE OR DELETE ON cash_balance_snapshots FOR EACH ROW EXECUTE FUNCTION audit_financial_change();
CREATE INDEX obligations_due ON obligations(store_id,currency,due_at);
CREATE INDEX rules_matching ON cost_rules(product_id,store_id,bundle_quantity,effective_start);
CREATE INDEX orders_store_date ON orders(store_id,ordered_at);
CREATE INDEX sessions_expiry ON sessions(expires_at);
-- Direct browser DB access is unsupported: server credentials only. Do not expose these tables through an anonymous Supabase role.
REVOKE ALL ON ALL TABLES IN SCHEMA company_os FROM PUBLIC;

REVOKE ALL ON SCHEMA company_os FROM PUBLIC;
